<style>
:root{--paper:#effcf7;--ink:#063b34;--emerald:#00a884;--mint:#78f0c5;--white:#fff;--line:rgba(6,59,52,.12)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:inherit;text-decoration:none}.container{width:min(1240px,calc(100% - 40px));margin-inline:auto}.site-header{position:fixed;z-index:50;inset:0 0 auto;background:rgba(239,252,247,.75);backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.header-inner{height:76px;display:flex;align-items:center;justify-content:space-between}.brand{font-weight:800;letter-spacing:-.03em}.hero{min-height:100svh;padding:132px 0 72px;display:grid;align-items:center}.hero-grid{display:grid;grid-template-columns:minmax(0,.95fr) minmax(420px,1.05fr);gap:56px;align-items:center}.hero h1{font-size:clamp(3.4rem,6.5vw,6.9rem);line-height:.93;letter-spacing:-.065em;margin:20px 0 24px}.hero h1 span{background:linear-gradient(100deg,#008d73,#00c99c,#28a8d8);-webkit-background-clip:text;color:transparent}.hero p{font-size:clamp(1.05rem,1.4vw,1.25rem);line-height:1.7;max-width:640px}.globe-shell{position:relative;aspect-ratio:1;border-radius:50%;min-height:520px}.globe-fallback{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 30px 70px rgba(0,122,100,.25))}@media(max-width:900px){.hero-grid{grid-template-columns:1fr}.globe-shell{min-height:360px;max-width:620px;margin:auto}.hero{padding-top:112px}.hero h1{font-size:clamp(3rem,13vw,5.3rem)}}
</style>
